package kr.remerge.stylehub.domain.negotiation.cache;

import java.time.Duration;
import java.util.concurrent.ThreadLocalRandom;

public class NegotiationListCache {
    private static final Duration TTL = Duration.ofSeconds(60);
    private static final int JITTER_SECONDS = 15;

    // 여러 구매자의 캐시가 같은 순간 만료되지 않도록 TTL에 0~15초 무작위 값을 더한다
    Duration ttlFor(Long buyerId) {
        return TTL.plusSeconds(ThreadLocalRandom.current().nextInt(JITTER_SECONDS + 1));
    }
}

