package kr.remerge.stylehub.domain.negotiation.cache;

import org.junit.jupiter.api.RepeatedTest;
import static org.assertj.core.api.Assertions.assertThat;

class NegotiationListCacheTest {
    @RepeatedTest(50)
    void ttlFor_60초에서_75초_사이() {
        long s = new NegotiationListCache().ttlFor(1L).getSeconds();
        assertThat(s).isBetween(60L, 75L);
    }
}
